# Sourced profile facts for content/county/commissioners/<slug>.json. Every sentence carries a source key.
# Bios are short neutral paraphrases of the cited official County district Biography page (current, or an
# archived copy on web.archive.org from the commissioner's tenure). No opinions; nothing added beyond the source.
RET = 'retrieved 2026-11-19'
CUR = 'https://discover.pbc.gov/countycommissioners/district{}/Pages/Biography.aspx'
WB = {
 'hal-valeche': 'https://web.archive.org/web/20190809144928/http://discover.pbcgov.org/countycommissioners/district1/Pages/Biography.aspx',
 'gregg-weiss': 'https://web.archive.org/web/20250520154449/https://discover.pbcgov.org/countycommissioners/district2/Pages/Biography.aspx',
 'dave-kerner': 'https://web.archive.org/web/20210123022344/https://discover.pbcgov.org/countycommissioners/district3/Pages/Biography.aspx',
 'michael-barnett': 'https://web.archive.org/web/20240228172139/https://discover.pbcgov.org/countycommissioners/district3/Pages/Biography.aspx',
 'robert-weinroth': 'https://web.archive.org/web/20210613090851/https://discover.pbcgov.org/countycommissioners/district4/pages/biography.aspx',
 'mary-lou-berger': 'https://web.archive.org/web/20190809144954/http://discover.pbcgov.org/countycommissioners/District5/Pages/Biography.aspx',
 'melissa-mckinlay': 'https://web.archive.org/web/20210508162304/https://discover.pbcgov.org/countycommissioners/district6/Pages/Biography.aspx',
 'sara-baxter': 'https://web.archive.org/web/20250622102248/https://discover.pbcgov.org/countycommissioners/district6/Pages/Biography.aspx',
 'mack-bernard': 'https://web.archive.org/web/20231205022330/https://discover.pbc.gov/countycommissioners/district7/Pages/Biography.aspx',
}
def wbsrc(slug, label):
    ts = WB[slug].split('/web/')[1][:8]
    return {'label': f'{label} (official County district Biography page, archived {ts[:4]}-{ts[4:6]}-{ts[6:]})', 'url': WB[slug]}
def cursrc(d, label):
    return {'label': f'{label} (official County district Biography page, {RET})', 'url': CUR.format(d)}

